use vstd::prelude::*;

verus! {
    spec fn count_eligible(participations: &[u8], k: u8) -> usize
        requires
            participations.len() <= 255,
            k <= 5,
    {
        participations.iter()
            .filter(|&&attendance_count| 5 - attendance_count >= k)
            .count()
    }

    fn count_eligible_impl(participations: &[u8], k: u8) -> (count: usize)
        requires
            participations.len() <= 255,
            k <= 5,
        ensures
            count == count_eligible(participations, k),
    {
        let count = participations.iter()
            .filter(|&&attendance_count| 5 - attendance_count >= k)
            .count();
        count
    }

    fn solve(n: u8, k: u8, participations: Vec<u8>) -> (result: u8)
        requires
            n <= participations.len() as u8,
            k <= 5,
        ensures
            result == (count_eligible(&participations[..n as usize], k) / 3) as u8,
    {
        let relevant_participations = &participations[..n.min(participations.len() as u8) as usize];
        
        let eligible_count = count_eligible_impl(relevant_participations, k);
        
        (eligible_count / 3) as u8
    }

    fn main() {
        let n = 5;
        let k = 2;
        let participations = vec![1, 2, 3, 4, 5, 0];
        
        let result = solve(n, k, participations);
        println!("Maximum number of teams: {}", result);
    }
}